package com.clavis.reader;
import android.app.*;import android.content.*;import android.view.*;import android.widget.*;import androidx.recyclerview.widget.*;import org.json.*;import java.util.*;
final class PodcastDirectoryChecks {
 static int checks;static void check(boolean yes,String message){checks++;if(!yes)throw new AssertionError(message);}
 static View find(View v,String text){if(v instanceof TextView&&((TextView)v).getText().toString().equals(text))return v;if(v instanceof ViewGroup)for(int n=0;n<((ViewGroup)v).getChildCount();n++){View result=find(((ViewGroup)v).getChildAt(n),text);if(result!=null)return result;}return null;}
 static RecyclerView list(View v){if(v instanceof RecyclerView&&((RecyclerView)v).getAdapter() instanceof PodcastDirectory.DirectoryAdapter)return (RecyclerView)v;if(v instanceof ViewGroup)for(int n=0;n<((ViewGroup)v).getChildCount();n++){RecyclerView result=list(((ViewGroup)v).getChildAt(n));if(result!=null)return result;}return null;}
 static String run(Instrumentation test)throws Exception{checks=0;Context c=test.getTargetContext();JSONArray directory=PodcastDirectory.entries(c),defaults=FeedCatalog.catalog(c);check(directory.length()==500,"Exactly 500 podcast catalog entries");HashSet<String> urls=new HashSet<>();for(int n=0;n<directory.length();n++){JSONObject e=directory.getJSONObject(n);check(urls.add(e.getString("url")),"Unique podcast feed");check(e.getString("url").startsWith("https://"),"HTTPS public feed");check(!e.getString("image").isEmpty(),"Podcast artwork metadata");check(PodcastDirectory.filter(directory,e.getString("title")).stream().anyMatch(x->x.optString("url").equals(e.optString("url"))),"Every catalog title searchable");}int count=0;for(int n=0;n<defaults.length();n++)if(defaults.getJSONObject(n).getString("kind").equals("Podcasts")&&defaults.getJSONObject(n).optBoolean("preload"))count++;check(count==50,"Fifty default podcast sources");check(PodcastDirectory.filter(directory,"").size()==500,"Empty query exposes entire directory");check(PodcastDirectory.filter(directory,"zzzzzz_no_such_podcast").isEmpty(),"Unmatched catalog search is empty");MainActivity a=(MainActivity)test.startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));try{test.runOnMainSync(()->{FeedRefresh.forget(a);FeedScreens.show(a,"Podcasts",true);check(find(a.mainFrame,"Browse")!=null,"Podcast Browse tab visible");check(find(a.mainFrame,"My podcasts")!=null,"My podcasts tab visible");check(find(a.mainFrame,"Add RSS feed")==null&&find(a.mainFrame,"Feeds / refresh")==null,"Podcast management buttons removed");check(FeedExperienceChecks.pull(a.mainFrame),"My podcasts supports pull to refresh");check(find(a.mainFrame,"Search podcasts online")==null,"Standalone search moved into Browse");PodcastDirectory.show(a);RecyclerView rv=list(a.mainFrame);check(rv!=null&&rv.getAdapter().getItemCount()==500,"Browse uses virtualized 500-show list");PodcastDirectory.DirectoryAdapter adapter=(PodcastDirectory.DirectoryAdapter)rv.getAdapter();try{JSONObject first=directory.getJSONObject(0),extra=new JSONObject().put("url","https://example.invalid/new-feed").put("title","Online result");int added=adapter.append(new JSONArray().put(first).put(extra));check(added==1&&adapter.getItemCount()==501,"Online results append while duplicate catalog shows are removed");adapter.set(PodcastDirectory.filter(directory,directory.getJSONObject(499).getString("title")));check(adapter.rows.stream().anyMatch(e->e.optString("url").equals(directory.optJSONObject(499).optString("url"))),"Final catalog item accessible through search");}catch(Exception error){throw new RuntimeException(error);}check(a.screen.equals("Podcasts browse"),"Browse navigation state");a.onBackPressed();check(a.screen.equals("Podcasts")&&a.feedSources,"Back returns to My podcasts");FeedScreens.show(a,"Podcasts",false);check(FeedExperienceChecks.pull(a.mainFrame),"Popular podcasts supports pull to refresh");for(FeedStore.Feed feed:FeedStore.load(a))if(feed.kind.equals("Podcasts")){FeedScreens.items(a,feed);check(FeedExperienceChecks.pull(a.mainFrame),"Podcast episodes support pull to refresh");check(find(a.mainFrame,"Refresh feed")==null,"Episode refresh button removed");break;}for(String kind:new String[]{"News","Journals"}){FeedScreens.show(a,kind,true);check(find(a.mainFrame,"My list")!=null,"My list tab for "+kind);check(find(a.mainFrame,"Sources")==null,"Old Sources label removed for "+kind);check(find(a.mainFrame,"Add RSS feed")==null&&find(a.mainFrame,"Feeds / refresh")==null,"Redundant feed buttons removed for "+kind);check(FeedExperienceChecks.pull(a.mainFrame),"My list supports pull to refresh for "+kind);}});test.waitForIdleSync();test.runOnMainSync(()->PodcastDirectory.show(a));test.waitForIdleSync();android.os.SystemClock.sleep(300);test.runOnMainSync(()->{RecyclerView rv=list(a.mainFrame);check(ScrollChrome.active.containsKey(rv),"Browse has scroll-responsive navigation");rv.scrollBy(0,a.dp(240));});android.os.SystemClock.sleep(350);test.waitForIdleSync();test.runOnMainSync(()->{check(a.bar.getHeight()==0,"Scrolling down hides top navigation");list(a.mainFrame).scrollBy(0,-a.dp(80));});android.os.SystemClock.sleep(350);test.waitForIdleSync();test.runOnMainSync(()->check(a.bar.getHeight()>0,"Scrolling up restores top navigation"));}finally{test.runOnMainSync(a::finish);}return checks+" podcast directory, combined search and navigation checks passed\n";}
}
